begin;

alter table public.builders add column if not exists jurisdiction text;
update public.builders
set jurisdiction = case
  when registration_number like 'CDB-L %' then 'VIC'
  when registry_url like 'https://verify.licence.nsw.gov.au/%' then 'NSW'
  when upper(coalesce(nullif(jurisdiction, ''), state, 'VIC')) in ('VIC', 'NSW')
    then upper(coalesce(nullif(jurisdiction, ''), state, 'VIC'))
  else 'VIC'
end
where jurisdiction is null
   or jurisdiction = ''
   or registration_number like 'CDB-L %'
   or registry_url like 'https://verify.licence.nsw.gov.au/%';
alter table public.builders alter column jurisdiction set not null;
alter table public.builders alter column jurisdiction set default 'VIC';
alter table public.builders drop constraint if exists builders_jurisdiction_check;
alter table public.builders add constraint builders_jurisdiction_check
  check (jurisdiction in ('VIC', 'NSW'));

drop index if exists public.builders_registration_number_key;
create unique index builders_jurisdiction_registration_number_key
  on public.builders(jurisdiction, registration_number)
  where registration_number is not null;
create index if not exists builders_jurisdiction_active_idx
  on public.builders(jurisdiction, active, verified);

create table if not exists public.australian_postcode_centroids (
  jurisdiction text not null check (jurisdiction in ('VIC', 'NSW')),
  postcode text not null,
  latitude numeric(9,6) not null,
  longitude numeric(9,6) not null,
  source text not null default 'G-NAF locality centroid',
  primary key (jurisdiction, postcode)
);
alter table public.australian_postcode_centroids enable row level security;

select 'VIC', postcode, latitude, longitude, source
from public.vic_postcode_centroids
on conflict (jurisdiction, postcode) do update set
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  source = excluded.source;

drop function if exists public.find_matching_builders(text, text, numeric, numeric, integer);
drop function if exists public.find_matching_builders(text, text, text, numeric, numeric, integer);
create function public.find_matching_builders(
  p_postcode text,
  p_suburb text default null,
  p_state text default null,
  p_latitude numeric default null,
  p_longitude numeric default null,
  p_limit integer default 12
)
returns table (
  builder_id uuid,
  builder_name text,
  suburb text,
  state text,
  description text,
  logo_url text,
  registration_number text,
  distance_km numeric
)
language sql
stable
security definer
set search_path = ''
as $$
  with requested as (
    select upper(trim(coalesce(p_state, ''))) as jurisdiction
  ), target as (
    select
      r.jurisdiction,
      coalesce(p_latitude, pc.latitude) as latitude,
      coalesce(p_longitude, pc.longitude) as longitude
    from requested r
    left join public.australian_postcode_centroids pc
      on pc.jurisdiction = r.jurisdiction
     and pc.postcode = trim(p_postcode)
  ), candidates as (
    select
      b.id,
      b.name,
      b.suburb,
      b.state,
      b.description,
      b.logo_url,
      b.registration_number,
      b.postcode = trim(p_postcode) as same_postcode,
      case
        when t.latitude is not null and t.longitude is not null and b.latitude is not null and b.longitude is not null
        then round((6371 * acos(least(1, greatest(-1,
          cos(radians(t.latitude)) * cos(radians(b.latitude)) *
          cos(radians(b.longitude) - radians(t.longitude)) +
          sin(radians(t.latitude)) * sin(radians(b.latitude))
        ))))::numeric, 1)
        else null
      end as calculated_distance
    from public.builders b
    cross join target t
    where b.active
      and b.verified
      and coalesce(b.registration_status, 'Current') = 'Current'
      and b.jurisdiction = t.jurisdiction
  )
  select c.id, c.name, c.suburb, c.state, c.description, c.logo_url,
         c.registration_number, c.calculated_distance
  from candidates c
  order by c.calculated_distance nulls last, c.same_postcode desc, c.name
  limit least(greatest(coalesce(p_limit, 12), 1), 30);
$$;
revoke all on function public.find_matching_builders(text, text, text, numeric, numeric, integer) from public;
grant execute on function public.find_matching_builders(text, text, text, numeric, numeric, integer) to anon, authenticated;

-- BEGIN GENERATED NSW DIRECTORY
on conflict (jurisdiction, postcode) do update set
  latitude = excluded.latitude, longitude = excluded.longitude, source = excluded.source;

on conflict (jurisdiction, registration_number) where registration_number is not null do update set
  name=excluded.name, slug=excluded.slug, email=excluded.email, phone=excluded.phone, website=excluded.website, description=excluded.description, address=excluded.address, suburb=excluded.suburb, state=excluded.state, postcode=excluded.postcode, latitude=excluded.latitude, longitude=excluded.longitude, verified=excluded.verified, active=excluded.active, registration_status=excluded.registration_status, registry_url=excluded.registry_url, registry_checked_at=excluded.registry_checked_at, limitations=excluded.limitations, contact_source=excluded.contact_source, coordinate_source=excluded.coordinate_source, updated_at=now();
-- END GENERATED NSW DIRECTORY

commit;
